// Get the output string from the previous node
const outputString = $input.first().json.output;

console.log('Raw output:', outputString);

try {
  let parsedData;

  // Try to parse directly as JSON first
  try {
    parsedData = JSON.parse(outputString);
    console.log('Parsed as direct JSON');
  } catch (e) {
    // If direct parsing fails, try to extract JSON from code blocks

    // Match various code block formats: ```json ... ```, ```...```, or just raw JSON
    const codeBlockMatch = outputString.match(/```(?:json)?\s*([\s\S]*?)\s*```/);

    if (codeBlockMatch && codeBlockMatch[1]) {
      console.log('Extracted from code block');
      parsedData = JSON.parse(codeBlockMatch[1]);
    } else {
      // Try to find JSON object/array patterns in the string
      const jsonMatch = outputString.match(/(\{[\s\S]*\}|\[[\s\S]*\])/);

      if (jsonMatch) {
        console.log('Extracted JSON pattern');
        parsedData = JSON.parse(jsonMatch[1]);
      } else {
        throw new Error('No JSON found in output');
      }
    }
  }

  console.log('Parsed data:', JSON.stringify(parsedData, null, 2));

  // Return the parsed data as-is (generic, no assumptions about structure)
  return {
    plan: parsedData
  };

} catch (error) {
  console.log('Error parsing JSON:', error.message);
  return [{
    json: {
      error: 'Failed to parse JSON',
      message: error.message,
      rawOutput: outputString
    }
  }];
}
